// i18n types — derived from zh/index.json (SSOT).
//
// History: previously generated by typesafe-i18n's CLI, whose generator is
// incompatible with TypeScript 7 (`ts.createProgram` removed from the npm
// package). Types now derive from the JSON dictionary directly: adding a key
// to zh/index.json automatically extends `Translation`.

import zh from './zh/index.json' with { type: 'json' };

export type BaseLocale = 'zh';

export type Locales = 'zh';

export type Translation = Record<keyof typeof zh, string>;
